import ast
import io
import csv


def eval_number(text: str) -> int:
    try:
        return int(ast.literal_eval(text.strip()))
    except (ValueError, TypeError):
        raise ValueError(f"Invalid number format: {text}")


def export_rows(rows: list[tuple[str, int]]) -> str:
    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(["id", "name"])
    for row in rows:
        writer.writerow([row[0], row[1]])
    return output.getvalue()

